/* ============================================================
   ① 全局变量
   ============================================================ */
:root {
  /* 气泡配色：双方统一 */
  --me-bg: #f5f5f6;
  --them-bg: #f5f5f6;
  --bubble-text: #6b6f7a;

  /* 表情反应 */
  --react-gap: 14px;          /* 给反应气泡留的高度（头像不在上方了，所以比旧版大） */
  --plain-reaction-extra-gap: 0px;
  --reaction-badge-size: 11px;
  --react-x: 13px;            /* 徽章往外移多少 */
  --react-y: -10px;           /* 徽章上下位置：越小越贴近气泡 */
}

/* ============================================================
   ② 顶栏：头像 + 昵称 + 蓝标 + id + 图床大图 + 两个伪按钮
   ============================================================ */
:root {
  --chat-header-height: calc(210px + env(safe-area-inset-top, 0px));
  --chat-header-bg: #ffffff;
  --chat-header-blur: 0px;
  --chat-header-border: #efefef;
  --chat-header-title-color: #000;
