/* ============================================================
   ③ 气泡：柔雾灰 + 每条都有的小尾巴（九宫格背景）
   ============================================================ */
:root {
  --bubble-me-bg: #f5f5f6;  --bubble-me-color: #6b6f7a;
  --bubble-me-border: none; --bubble-me-shadow: none;
  --bubble-me-padding: 7px 14px;
