/* 引用消息：分别调整双方头像位置 */
.msg-bubble-wrapper.msg-me:has(.msg-reply-block-detached) .msg-avatar-me-container {
  margin-top: 55px !important;
}
.msg-bubble-wrapper.msg-them:has(.msg-reply-block-detached) .msg-avatar-them-container {
  margin-top: 0 !important;
  align-self: flex-end !important;
}

/* 对方「思维链」胶囊：文字换成 id */
.nuo-thinking-arrow, .nuo-thinking-icon { display: none !important; }
.nuo-thinking-btn {
  background: transparent !important; border: none !important; box-shadow: none !important;
  padding: 0 0 0 2px !important; height: 20px;
  display: inline-flex !important; align-items: center;
}
.nuo-thinking-wrap { gap: 2px; --thinking-wrap-gap: 2px; }
.nuo-thinking-label { font-size: 0 !important; }
.nuo-thinking-label::after {
  content: "@urxuanivqe_o";
  font-family: -apple-system, "Helvetica Neue", Arial, sans-serif;
  font-size: 12.5px; color: #8e8e93;
}
.nuo-thinking-panel {
  margin-top: 2px !important;
  max-width: calc(100vw - 60px) !important;
}
/* 有思维链时，头像往下对准气泡 */
.msg-bubble-wrapper:has(.nuo-thinking-wrap) .msg-avatar-them-container {
  margin-top: 22px !important;
}
/* 引用 + 思维链同时存在：思维链上移到最顶，引用条往下让位 */
.msg-content-stack:has(.msg-reply-block-detached) .nuo-thinking-wrap:not(.is-open) {
  transform: translateY(-51px);
}
.msg-content-stack:has(.nuo-thinking-wrap:not(.is-open)) .msg-reply-block-detached {
  transform: translateY(24px);
}

/* ============================================================
   ⑤ 表情反应：移到气泡上方，做成想法气泡（旧主题保留，已改灰）
   ============================================================ */
.msg-bubble-wrapper.has-reactions {
  margin-top: var(--react-gap) !important;
}

/* 徽章本体：正圆，紧贴气泡，带白边 */
.msg-reaction-badge {
  --ring: 1.5px;
  --ring-color: #fff;
  top: auto !important;
  bottom: calc(100% + var(--react-y)) !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  box-sizing: border-box !important;
  min-width: 22px !important;
  height: 22px !important;
  padding: 0 5px !important;
  border: none !important;
  border-radius: 999px !important;
  box-shadow: none !important;
  z-index: 3;
  filter:
    drop-shadow(var(--ring) 0 0 var(--ring-color))
    drop-shadow(calc(-1 * var(--ring)) 0 0 var(--ring-color))
    drop-shadow(0 var(--ring) 0 var(--ring-color))
    drop-shadow(0 calc(-1 * var(--ring)) 0 var(--ring-color)) !important;
}
.msg-reaction-emoji {
  font-size: 11px !important;
  line-height: 1 !important;
}
.msg-reaction-badge-me {
  left: calc(-1 * var(--react-x)) !important;
  right: auto !important;
  background: var(--me-bg) !important;
}
.msg-reaction-badge-them {
  right: calc(-1 * var(--react-x)) !important;
  left: auto !important;
  background: var(--them-bg) !important;
}
/* 尾巴：两颗圆点朝外 */
.msg-reaction-badge::before,
.msg-reaction-badge::after {
  content: "";
  position: absolute;
  border-radius: 50%;
  background: inherit;
}
.msg-reaction-badge::before { width: 8px; height: 8px; bottom: -2px; }
.msg-reaction-badge::after  { width: 4px; height: 4px; bottom: -8px; }
.msg-reaction-badge-them::before { right: -1px; left: auto; }
.msg-reaction-badge-them::after  { right: -7px; left: auto; }
.msg-reaction-badge-me::before { left: -1px; right: auto; }
.msg-reaction-badge-me::after  { left: -7px; right: auto; }

/* ============================================================
   ⑥ 语音：颜色 / 圆角同步新气泡（灰底 #f5f5f6 + 字 #6b6f7a + 圆角 15px），条已改短
   ============================================================ */
.voice-msg {
  background: transparent !important; padding: 0 !important; margin: 0 !important;
  border: none !important; box-shadow: none !important; position: relative !important;
  width: fit-content !important;
}
.bubble-me-custom:has(.voice-msg), .bubble-them-custom:has(.voice-msg),
.msg-bubble-container:has(.voice-msg), .msg-content-stack:has(.voice-msg) {
  background: transparent !important; border: none !important; box-shadow: none !important;
  padding: 0 !important; border-radius: 0 !important;
  width: fit-content !important;
}
/* 语音条自己是气泡，不再叠九宫格尾巴（转文字展开时不会多出一块灰） */
.bubble-me-custom:has(.voice-msg)::after,
.bubble-them-custom:has(.voice-msg)::after { display: none !important; }

.voice-msg .voice-controls-row {
  display: flex !important; align-items: center !important; gap: 4px !important;
  height: auto !important; min-height: 0 !important; max-height: none !important;
  width: fit-content !important; max-width: 100% !important;
  padding: 4px 10px !important; box-sizing: border-box !important;
  background: var(--them-bg) !important; color: var(--bubble-text) !important;
  border: none !important; border-radius: 15px !important; box-shadow: none !important;
  position: relative !important; z-index: 4 !important; pointer-events: none !important;
}
.msg-me .voice-msg .voice-controls-row { background: var(--me-bg) !important; }

/* 播放 / 下载按钮 */
.voice-msg .voice-play-btn {
  background: transparent !important; border: none !important; padding: 0 !important;
  width: 18px !important; height: 18px !important; flex-shrink: 0 !important;
  display: flex !important; align-items: center !important; justify-content: center !important;
  color: inherit !important; cursor: pointer !important; pointer-events: auto !important;
  position: relative !important; z-index: 5 !important;
}
.voice-msg .voice-download-btn {
  background: transparent !important; border: none !important; padding: 0 !important; margin: 0 !important;
  flex-shrink: 0 !important; opacity: .7 !important;
  display: flex !important; align-items: center !important; justify-content: center !important;
  color: inherit !important; cursor: pointer !important; pointer-events: auto !important;
  position: relative !important; z-index: 5 !important;
}
.voice-msg .voice-play-btn svg, .voice-msg .voice-download-btn svg {
  fill: currentColor !important; color: inherit !important;
}
.voice-msg .voice-play-btn svg { width: 15px !important; height: 15px !important; }
.voice-msg .voice-download-btn svg { width: 14px !important; height: 14px !important; }

/* 波形：已播放亮，未播放淡 */
.voice-msg .voice-waveform {
  display: flex !important; align-items: center !important; gap: 1px !important;
  height: 20px !important; flex: 0 0 auto !important; width: auto !important; min-width: 0 !important;
  position: relative !important; z-index: 2 !important; pointer-events: none !important;
}
.voice-msg .voice-waveform-bar {
  width: 1.5px !important; border-radius: 2px !important; flex-shrink: 0 !important;
  background: currentColor !important; opacity: .35 !important;
}
.voice-msg .voice-waveform-bar.active { opacity: 1 !important; }

/* 时长 */
.voice-msg .voice-duration {
  font-size: 10px !important; font-weight: 400 !important; color: inherit !important; opacity: .75 !important;
  flex-shrink: 0 !important; min-width: 0 !important; text-align: left !important;
  font-variant-numeric: tabular-nums !important;
  position: relative !important; z-index: 2 !important; pointer-events: none !important;
}

/* 转文字切换：整块透明覆盖可点击 */
.voice-msg .voice-transcription-toggle {
  display: block !important; width: 100% !important; height: 100% !important;
  background: transparent !important; border: none !important; padding: 0 !important; margin: 0 !important;
  position: absolute !important; top: 0 !important; left: 0 !important; z-index: 3 !important;
  font-size: 0 !important; color: transparent !important; overflow: hidden !important;
  cursor: pointer !important; pointer-events: auto !important;
}
.voice-msg .voice-transcription-toggle * { display: none !important; }
.voice-msg .voice-transcription-toggle::before,
.voice-msg .voice-transcription-toggle::after { content: none !important; display: none !important; }

/* 转文字框：和气泡同款 */
.voice-msg .voice-transcription {
  display: block !important; margin-top: 6px !important; margin-bottom: 0 !important;
  padding: 7px 14px !important; box-sizing: border-box !important; max-width: 100% !important;
  font-size: 13px !important; line-height: 1.4 !important;
  background: var(--them-bg) !important; color: var(--bubble-text) !important;
  border: none !important; border-radius: 15px !important; box-shadow: none !important;
  word-break: break-word !important; overflow-wrap: break-word !important;
  position: relative !important; z-index: 1 !important; cursor: pointer !important;
}
.msg-me .voice-msg .voice-transcription { background: var(--me-bg) !important; }
.voice-msg .voice-transcription.hidden { display: none !important; }

/* 对齐 */
.msg-them .voice-msg { align-self: flex-start !important; }
.msg-me .voice-msg   { align-self: flex-end !important; }

/* ============================================================
   ⑦ 转账卡片：改成灰（上浅灰 / 下深一点灰，以分隔线为界）
   ============================================================ */
:root {
  --tf-top: #f5f5f6;      /* 上半：和气泡同色 */
  --tf-deep: #c4c4c4;     /* 下半 / 图标底 / 边框：和底栏图标同灰 */
  --tf-text: #8a8a8e;     /* 上半文字 */
  --tf-radius: 4px;
  --split: 73%;           /* 浅色区域占卡片高度的比例 */

  --transfer-card-width: 230px;
  --transfer-card-bg: #f5f5f6;
  --transfer-card-radius: 4px;
  --transfer-card-border: 1.5px solid #c4c4c4;
  --transfer-card-shadow: none;
  --transfer-icon-bg: #c4c4c4;
  --transfer-icon-color: #ffffff;
  --transfer-icon-size: 34px;
  --transfer-icon-svg-size: 18px;
  --transfer-amount-color: #8a8a8e;

  --transfer-success-card-bg: #f5f5f6;
  --transfer-success-card-border: 1.5px solid #c4c4c4;
  --transfer-success-icon-bg: #c4c4c4;
  --transfer-success-icon-color: #ffffff;
  --transfer-success-label-color: #8a8a8e;
  --transfer-rejected-card-bg: #f5f5f6;
  --transfer-rejected-card-border: 1.5px dashed #c4c4c4;
  --transfer-rejected-label-color: #b5b5ba;
  --transfer-expired-card-bg: #f5f5f6;
  --transfer-expired-card-border: 1.5px dashed #c4c4c4;
  --transfer-expired-label-color: #b5b5ba;

  --transfer-content-padding: 10px 14px;
  --transfer-header-margin-bottom: 0px;
}

/* 锁死宽高，不被内容撑变形；上浅下深 */
.chat-detail-screen .msg-transfer-card {
  position: relative !important;
  width: 230px !important;
  min-width: 230px !important;
  max-width: 230px !important;
  height: 102px !important;
  min-height: 102px !important;
  max-height: 112px !important;
  padding-top: 10px !important;
  padding-bottom: 10px !important;
  box-sizing: border-box !important;
  overflow: hidden !important;
  flex: 0 0 auto !important;
  background: linear-gradient(
    to bottom,
    var(--tf-top) 0,
    var(--tf-top) var(--split),
    var(--tf-deep) var(--split),
    var(--tf-deep) 100%
  ) !important;
  border: 1.5px solid var(--tf-deep) !important;
  border-radius: var(--tf-radius) !important;
  box-shadow: none !important;
  color: var(--tf-text) !important;
}
.chat-detail-screen .msg-transfer-card.msg-transfer-rejected,
.chat-detail-screen .msg-transfer-card.msg-transfer-expired-card {
  border: 1.5px dashed var(--tf-deep) !important;
  opacity: 0.8;
}

.chat-detail-screen .msg-transfer-label {
  font-size: 12px !important;
  white-space: nowrap !important;
  color: var(--tf-text) !important;
}
.chat-detail-screen .msg-transfer-card.msg-transfer-success .msg-transfer-label {
  color: var(--tf-text) !important;
}
.chat-detail-screen .msg-transfer-subtitle {
  font-size: 11px !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  color: var(--tf-text) !important;
  transform: translateY(-47px) !important;
}
.chat-detail-screen .msg-transfer-status-text {
  font-size: 11px !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  color: rgba(255,255,255,0.92) !important;
  transform: translateY(-18px) !important;
}
.chat-detail-screen .msg-transfer-divider {
  background: transparent !important;
  transform: translateY(-18px) !important;
}

/* 金额：强制可见，固定在卡片上半 */
.chat-detail-screen .msg-transfer-card .msg-transfer-amount {
  position: absolute !important;
  top: 40% !important;
  left: 40% !important;
  transform: translate(-50%, -50%) !important;
  margin: 0 !important;
  text-align: center !important;
  width: auto !important;
  max-width: 60% !important;
  z-index: 2 !important;
  display: block !important;
  font-size: 22px !important;
  font-weight: 700 !important;
  line-height: 1 !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  color: var(--tf-text) !important;
  -webkit-text-fill-color: var(--tf-text) !important;
  background: none !important;
  -webkit-background-clip: border-box !important;
  background-clip: border-box !important;
  opacity: 1 !important;
  visibility: visible !important;
}

/* 图标：灰圆底 + 白图案 */
.chat-detail-screen .msg-transfer-card [class*="icon"] {
  background: var(--tf-deep) !important;
  color: #ffffff !important;
  width: 30px !important;
  height: 30px !important;
  min-width: 30px !important;
  flex-shrink: 0 !important;
  border-radius: 50% !important;
  transform: translateY(8px) !important;
}
.chat-detail-screen .msg-transfer-card [class*="icon"] svg {
  width: 16px !important;
  height: 16px !important;
  color: #ffffff !important;
  stroke: #ffffff !important;
  fill: none !important;
}
.chat-detail-screen .msg-transfer-card [class*="icon"] svg * {
  stroke: #ffffff !important;
}
.chat-detail-screen .msg-transfer-card img {
  max-width: none !important;
  max-height: none !important;
}
/* 隐藏绿色打勾 */
.chat-detail-screen .msg-transfer-card .msg-transfer-check {
  display: none !important;
}

/* ============================================================
   ⑧ 图片 / 表情包 / 卡片类消息
   ============================================================ */

/* 表情包去气泡（带引用的气泡不算）：透明、去尾巴 */
body .chat-detail-screen .bubble-me-custom:has(img):not(:has(.msg-reply-block-detached, .msg-reply-block, .msg-reply-detached-media)),
body .chat-detail-screen .bubble-them-custom:has(img):not(:has(.msg-reply-block-detached, .msg-reply-block, .msg-reply-detached-media)) {
  background: transparent !important;
  background-image: none !important;
  border: none !important;
  box-shadow: none !important;
  border-radius: 0 !important;
  padding: 0 !important;
  min-width: 0 !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}
body .chat-detail-screen .bubble-me-custom:has(img):not(:has(.msg-reply-block-detached, .msg-reply-block, .msg-reply-detached-media))::after,
body .chat-detail-screen .bubble-them-custom:has(img):not(:has(.msg-reply-block-detached, .msg-reply-block, .msg-reply-detached-media))::after {
  display: none !important;
}
body .chat-detail-screen .bubble-me-custom:has(img):not(:has(.msg-reply-block-detached, .msg-reply-block, .msg-reply-detached-media)) img,
body .chat-detail-screen .bubble-them-custom:has(img):not(:has(.msg-reply-block-detached, .msg-reply-block, .msg-reply-detached-media)) img {
  max-width: 110px !important;
  max-height: 110px !important;
  width: auto !important;
  height: auto !important;
  object-fit: contain !important;
  border-radius: 0 !important;
}

/* 图片消息：紧贴照片的圆角卡片 + 往右上叠两层 */
:root {
  --img-card-bg: transparent;
  --img-card-pad: 0px;
  --img-card-radius: 16px;
  --img-photo-max-w: 170px;
  --img-photo-max-h: 220px;

  --img-w: 160px;          /* 实体图宽度 */
  --img-ratio: 3 / 4;
  --img-h: calc(var(--img-w) * 4 / 3);   /* 3:4 竖图 */
  --st-r: 16px;            /* 圆角 */
  --st-gap1: 9px;          /* 第二层往右露出多少 */
  --st-gap2: 18px;         /* 第三层往右露出多少 */
  --st-in1: 8px;           /* 第二层上下各缩进多少 */
  --st-in2: 16px;          /* 第三层上下各缩进多少 */

  --st-img1: url("https://imgbed.heliar.top/i/AoWSNPrYAvUTSCSf_IMG_1728.jpeg");
  --st-img2: url("https://imgbed.heliar.top/i/io2K1M6kBjymMS4Z_IMG_1726.jpeg");
  --st-f1: none;
  --st-f2: none;
}
body.dark-mode {
  --st-f1: grayscale(0.5) blur(1.5px) brightness(0.6);
  --st-f2: grayscale(0.9) blur(2.5px) brightness(0.45);
}

.msg-image-wrapper,
.msg-image-card {
  box-sizing: border-box !important;
  display: block !important;
  position: relative !important;
  isolation: isolate !important;
  min-width: 0 !important;
  min-height: 0 !important;
  max-width: 100% !important;
  padding: var(--img-card-pad) !important;
  background: var(--img-card-bg) !important;
  border: none !important;
  line-height: 0 !important;
  overflow: visible !important;
  filter: none !important;
  opacity: 1 !important;
  width: var(--img-w) !important;
  height: auto !important;
  aspect-ratio: var(--img-ratio) !important;
  box-shadow: none !important;
  border-radius: var(--st-r) !important;
  margin: 0 calc(var(--st-gap2) + 2px) 0 0 !important;
}
.msg-image-wrapper > *,
.msg-image-card > * {
  min-width: 0 !important;
  min-height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
}
body .chat-detail-screen .msg-image-wrapper,
body .chat-detail-screen .msg-image-card {
  width: var(--img-w) !important;
  height: var(--img-h) !important;
}
body .chat-detail-screen .msg-image-wrapper > *,
body .chat-detail-screen .msg-image-card > * {
  width: 100% !important;
  height: 100% !important;
}
body .chat-detail-screen .msg-image-wrapper img,
body .chat-detail-screen .msg-image-card img {
  display: block !important;
  width: 100% !important;
  height: 100% !important;
  max-width: none !important;
  max-height: none !important;
  object-fit: cover !important;
  border-radius: var(--st-r) !important;
  box-shadow: none !important;
}
body .chat-detail-screen .bubble-me-custom:has(img) .msg-image-wrapper img,
body .chat-detail-screen .bubble-them-custom:has(img) .msg-image-wrapper img,
body .chat-detail-screen .bubble-me-custom:has(img) .msg-image-card img,
body .chat-detail-screen .bubble-them-custom:has(img) .msg-image-card img {
  width: 100% !important;
  height: 100% !important;
  max-width: none !important;
  max-height: none !important;
  object-fit: cover !important;
  border-radius: var(--st-r) !important;
}

/* 后两层（用图床图片） */
.msg-image-wrapper::before,
.msg-image-card::before,
.msg-image-wrapper::after,
.msg-image-card::after {
  content: "" !important;
  display: block !important;
  position: absolute !important;
  border-radius: var(--st-r) !important;
  background-size: cover !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  pointer-events: none !important;
}
.msg-image-wrapper::before,
.msg-image-card::before {
  top: var(--st-in1) !important;
  bottom: var(--st-in1) !important;
  left: var(--st-gap1) !important;
  right: calc(-1 * var(--st-gap1)) !important;
  background-image: var(--st-img1) !important;
  filter: var(--st-f1) !important;
  z-index: -1 !important;
}
.msg-image-wrapper::after,
.msg-image-card::after {
  top: var(--st-in2) !important;
  bottom: var(--st-in2) !important;
  left: var(--st-gap2) !important;
  right: calc(-1 * var(--st-gap2)) !important;
  background-image: var(--st-img2) !important;
  filter: var(--st-f2) !important;
  z-index: -2 !important;
}

/* 视频卡：封面保持原比例，不被图片缩小规则影响 */
body .chat-detail-screen .bubble-me-custom .msg-video-card img,
body .chat-detail-screen .bubble-them-custom .msg-video-card img,
body .chat-detail-screen .bubble-me-custom .msg-video-card video,
body .chat-detail-screen .bubble-them-custom .msg-video-card video,
body .chat-detail-screen .bubble-me-custom .msg-video-card canvas,
body .chat-detail-screen .bubble-them-custom .msg-video-card canvas {
  width: 100% !important;
  height: 100% !important;
  max-width: none !important;
  max-height: none !important;
  object-fit: cover !important;
  border-radius: inherit !important;
}

/* 卡片类消息：不要气泡包裹，也不要小尾巴 */
body .chat-detail-screen :is(.bubble-me-custom, .bubble-them-custom):has(:is(
  .msg-transfer-card, .msg-redpacket-card, .msg-loc-card, .msg-videocall-card,
  .msg-gift-card, .msg-history-card, .msg-game-result-card,
  .msg-delivery-card, .msg-shop-order-card, .nuo-payreq-card, .nuo-payverdict-card,
  .msg-file-card, .peekask-card, .msg-group-invite-card, .msg-qa-share-card,
  .msg-video-card, .flash-card, .lp-card, .ext-share-card, .cc-card,
  .alarm-set-card, .msg-music-card, .msg-flea-share-card, .msg-mcp-trace,
  .msg-shopask-card, .bond-card-bubble, .msg-theater-card,
  .msg-offline-invite-card, .msg-couples-invite-card, .msg-couples-response-card,
  .msg-werewolf-card, .msg-mahjong-card, .msg-test-invite-card,
