/* ============================================================
   ⑨ 翻译：隐藏「查看翻译」，点气泡展开 → 白字黑描边
   ============================================================ */

/* 气泡内：翻译区脱离排版流，不占任何高度 */
.msg-translation-wrapper {
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  width: 100% !important;
  height: 100% !important;
  margin: 0 !important;
  padding: 0 !important;
  border: none !important;
  overflow: visible !important;
  pointer-events: none !important;
  z-index: 3 !important;
}
.msg-translation-wrapper .msg-translation-content { display: none !important; }

/* 按钮：不可见，但铺满整个气泡，可点击 */
.bubble-them-custom,
.bubble-me-custom {
  gap: 0 !important;
  row-gap: 0 !important;
}
.msg-translation-btn {
  display: block !important;
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  width: 100% !important;
  height: 100% !important;
  margin: 0 !important;
  padding: 0 !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  font-size: 0 !important;
  color: transparent !important;
  opacity: 1 !important;
  overflow: hidden !important;
  cursor: pointer !important;
  pointer-events: auto !important;
  z-index: 3 !important;
}
.msg-translation-btn *,
.msg-translation-btn svg,
.msg-translation-btn span { display: none !important; }
.msg-translation-btn::before,
.msg-translation-btn::after {
  display: none !important;
  content: none !important;
}

/* 气泡外：点开后出现的独立翻译块 */
.msg-translation-detached {
  display: block !important;
  margin-top: -4px !important;
  max-width: 100% !important;
  width: fit-content !important;
  min-width: 0 !important;
  box-sizing: border-box !important;
  position: relative !important;
  z-index: 6 !important;
  pointer-events: none !important;
}
.msg-translation-detached-them { transform: translate(18px, -10px) !important; }
.msg-translation-detached-me   { transform: translate(-18px, -10px) !important; }

/* 翻译文字：去气泡，粗体 + 白字黑描边 */
.msg-translation-detached-content,
.msg-translation-detached-me .msg-translation-detached-content,
.msg-translation-detached-them .msg-translation-detached-content {
  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  padding: 2px 0 !important;
  font-size: 13px !important;
  font-weight: 700 !important;
  line-height: 1.5 !important;
  letter-spacing: 0.5px !important;
  word-break: break-word !important;
  position: relative !important;

  color: #ffffff !important;
  -webkit-text-fill-color: #ffffff !important;
  -webkit-text-stroke: 2.5px #1D1B37 !important;
  paint-order: stroke fill !important;
  text-shadow: none !important;
}
.msg-translation-detached-me .msg-translation-detached-content { text-align: right !important; }

/* ============================================================
   ⑩ 底栏
   ============================================================ */
:root {
  /* 各按键位置：x 正数往右，y 正数往下，互不联动 */
  --plus-size: 34px;
  --plus-x: 10px;    --plus-y: -10px;
  --ai-x: 0px;       --ai-y: -4px;
  --send-x: 0px;     --send-y: -3px;
  --sticker-x: 0px;  --sticker-y: -4px;
  --mic-x: 0px;      --mic-y: calc(-1 * var(--row-up));
  --stop-y: -5px;                         /* AI 停止回复键 */

  /* 输入框 */
  --row-up: 5px;                          /* 输入框整体上移（与加号键齐平） */
  --text-up: var(--row-up);               /* 占位文案跟着上移 */
  --box-pt: 5px;                          /* 框内文字上方留白 */
  --box-pb: 3px;                          /* 框内文字下方留白：变大框就变高 */
  --ph-l: 13px;                           /* 占位文案区域：离输入栏左边 */
  --ph-r: 69px;                           /* 占位文案区域：离输入栏右边（表情键+AI 键的宽度） */

  --send-icon-size: 22px;                 /* 发送键图标大小 */
  --stop-btn-color: #c4c4c4;
  --stop-btn-bg: transparent;

  /* App 自带变量 */
  --input-area-bg: #ffffff;
  --input-area-bg-image: none;
  --input-area-blur: 0px;
  --input-box-font-size: 13px;
  --input-box-color: #bdbdbd;
  --input-box-placeholder: #bdbdbd;
  --input-caret-color: #bdbdbd;
}

/* 底栏整体：白底 */
.chat-detail-screen .input-area-custom {
  background: #ffffff !important;
  background-image: none !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

/* 输入框外壳：去掉框和底 */
.input-action-bar-custom {
  position: relative !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}
.input-btns-right { gap: 0 !important; }

/* 输入框本体：灰边白底方圆条，自适应高度，带滚动条 */
.input-box-custom { flex: 1 1 auto !important; min-width: 0 !important; }
#chat-detail-screen .input-box-custom {
  position: relative !important;
  top: calc(-1 * var(--row-up)) !important;
  box-sizing: border-box !important;
  min-height: 27px !important;
  max-height: 120px !important;
  height: auto !important;
  background: #ffffff !important;
  border: 1.5px solid #e4e4e4 !important;
  border-radius: 12px !important;
  box-shadow: none !important;
  padding-top: var(--box-pt) !important;
  padding-bottom: var(--box-pb) !important;
  padding-right: 38px !important;      /* 右边给框内的语音键让位 */
  overflow-y: auto !important;
  overflow-x: hidden !important;
  word-wrap: break-word !important;
  white-space: pre-wrap !important;
  resize: none !important;
  scrollbar-width: thin !important;
  scrollbar-color: #bdbdbd transparent !important;
  color: #bdbdbd !important;
  font-size: 13px !important;
}
#chat-detail-screen .input-box-custom:focus,
#chat-detail-screen .input-box-custom:active {
  color: #bdbdbd !important;
  font-size: 13px !important;
}
#chat-detail-screen .input-box-custom::-webkit-scrollbar { width: 4px !important; }
#chat-detail-screen .input-box-custom::-webkit-scrollbar-track { background: transparent !important; }
#chat-detail-screen .input-box-custom::-webkit-scrollbar-thumb {
  background: #bdbdbd !important;
  border-radius: 10px !important;
}

/* 占位符：原文隐藏，换成自己的文案（一输入就消失），文案居中 */
.input-box-custom::placeholder,
.input-box-custom::-webkit-input-placeholder {
  color: transparent !important;
  -webkit-text-fill-color: transparent !important;
  opacity: 0 !important;
}
.chat-detail-screen .input-area-custom .input-action-bar-custom:has(.input-box-custom:placeholder-shown)::before {
  content: "人世间千百种怨 不过是因为无缘";
  position: absolute;
  left: var(--ph-l) !important;
  right: var(--ph-r) !important;
  top: 50%;
  transform: translateY(calc(-50% - var(--text-up))) !important;
  text-align: center !important;
  font-size: 13px !important;
  letter-spacing: 0.08em;
  color: #bdbdbd !important;
  white-space: pre;
  pointer-events: none;
  z-index: 1;
}

/* 五个按键：各自独立位移 */
.input-btn-plus, .input-btn-ai, .send-btn-custom,
.input-btn-mic, .input-btn-sticker {
  position: relative !important;
  transform: none !important;
  margin: 0 !important;
}
.input-btn-plus    { left: var(--plus-x) !important;    top: var(--plus-y) !important; }
.input-btn-ai      { left: var(--ai-x) !important;      top: var(--ai-y) !important; }
.send-btn-custom   { left: var(--send-x) !important;    top: var(--send-y) !important; }
.input-btn-mic     { left: var(--mic-x) !important;     top: var(--mic-y) !important; }
.input-btn-sticker { left: var(--sticker-x) !important; top: var(--sticker-y) !important; }

