}

/* 语音键：隐藏但保持可点，压进输入框内最右端 */
.input-btn-mic,
.chat-detail-screen .input-btn-mic {
  opacity: 0 !important;
  pointer-events: auto !important;
  cursor: pointer !important;
  width: 32px !important;
  min-width: 16px !important;
  height: 27px !important;
  padding: 0 !important;
  flex-shrink: 0 !important;
}
.chat-detail-screen .input-btn-mic {
  margin: 0 0 0 -32px !important;
  z-index: 3 !important;
}

/* 发送键 → 信封 + 右箭头 */
.chat-detail-screen .input-area-custom .send-btn-custom,
.send-btn-custom {
  align-self: center !important;
  box-sizing: border-box !important;
  aspect-ratio: auto !important;
  width: 30px !important;
  min-width: 30px !important;
  height: 28px !important;
  min-height: 0 !important;
  max-height: 28px !important;
  padding: 0 !important;
  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  font-size: 0 !important;
  line-height: 1 !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
}
.send-btn-custom svg,
.send-btn-custom img { display: none !important; }
.chat-detail-screen .input-area-custom .send-btn-custom::after,
.send-btn-custom::after {
