/* ===== 跟随系统日夜：系统是深色时才生效 ===== */
@media (prefers-color-scheme: dark) {
  /* ===== 夜间样式：整段追加到你原 CSS 的最末尾 ===== */
  /* 想改颜色，只改下面这几个 --dk-xxx（气泡色还要连同尾巴里的 %231c1c1e 一起替换） */
  :root {
